def stimulus(rng, cycles):
    rows = []
    for i in range(cycles):
        if i < 4:
            rst = 1
            data_in = 0
            has_data = 0
        else:
            rst = 0
            phase = (i - 4) % 16
            if phase < 4:
                has_data = 1
                data_in = rng.randint(0, 15)
            elif phase < 8:
                has_data = 0
                data_in = rng.randint(0, 15)
            elif phase < 12:
                has_data = 1
                data_in = (i * 3 + 5) & 0xF
            else:
                has_data = 0
                data_in = 0
            if rng.random() < 0.05:
                rst = 1
                data_in = 0
                has_data = 0
        row = {
            'rst': rst & 0x1,
            'data_in': data_in & 0xF,
            'has_data_to_send': has_data & 0x1,
        }
        rows.append(row)
    return rows

def stimulus(rng, cycles):
    rows = []
    rst = 1
    data_in = 0
    has_data_to_send = 0
    for i in range(cycles):
        if i < 2:
            rst = 1
            data_in = 0
            has_data_to_send = 0
        elif i == 2:
            rst = 0
            data_in = 8
            has_data_to_send = 1
        elif i == 3:
            rst = 0
            data_in = 4
            has_data_to_send = 1
        elif i == 4:
            rst = 0
            data_in = 12
            has_data_to_send = 1
        elif i == 5:
            rst = 0
            data_in = 2
            has_data_to_send = 1
        else:
            rst = 0
            r = rng.random()
            if r < 0.12:
                data_in = rng.randrange(16)
            elif r < 0.22:
                data_in = (data_in + 1) & 0xF
            elif r < 0.30:
                data_in = (data_in << 1) & 0xF
            if rng.random() < 0.30:
                has_data_to_send = 1 - has_data_to_send
            if rng.random() < 0.10:
                has_data_to_send = 1
            if rng.random() < 0.06:
                has_data_to_send = 0
            if rng.random() < 0.03:
                rst = 1
                data_in = 0
                has_data_to_send = 0
        row = {
            'rst': rst & 0x1,
            'data_in': data_in & 0xF,
            'has_data_to_send': has_data_to_send & 0x1,
        }
        if rng.random() < 0.25:
            mid_data = data_in
            mid_send = has_data_to_send
            if rng.random() < 0.5:
                mid_data = rng.randrange(16)
            if rng.random() < 0.5:
                mid_send = rng.randrange(2)
            row['mid'] = {'data_in': mid_data & 0xF, 'has_data_to_send': mid_send & 0x1}
        rows.append(row)
    return rows

def stimulus(rng, cycles):
    rows = []
    rst_remaining = 3
    enc_run = 0
    dec_run = 0
    enc_data = 0
    dec_data = 0
    for i in range(cycles):
        rst = 1 if rst_remaining > 0 else 0
        if rst_remaining > 0:
            rst_remaining -= 1
        enc_valid = 0
        dec_valid = 0
        if rst == 0:
            if enc_run > 0:
                enc_valid = 1
                enc_run -= 1
            elif rng.random() < 0.4:
                enc_valid = 1
                enc_data = rng.randrange(256)
                enc_run = rng.randrange(1, 8)
            if dec_run > 0:
                dec_valid = 1
                dec_run -= 1
            elif rng.random() < 0.4:
                dec_valid = 1
                dec_data = rng.randrange(65536)
                dec_run = rng.randrange(1, 8)
        row = {
            'rst_in': rst,
            'enc_valid_in': enc_valid,
            'enc_data_in': enc_data if enc_valid else 0,
            'dec_valid_in': dec_valid,
            'dec_data_in': dec_data if dec_valid else 0,
        }
        if rst == 0 and rng.random() < 0.05:
            row['mid'] = {'rst_in': 1, 'enc_valid_in': 0, 'enc_data_in': 0,
                          'dec_valid_in': 0, 'dec_data_in': 0}
        rows.append(row)
    return rows
